<?php
namespace davvag_credit_points;
require_once __DIR__ . "/CreditLedgerService.php";
require_once __DIR__ . "/CreditCurrencyAdapter.php";
class CreditPaymentService {
    private $ledger;
    private $currency;
    public function __construct($ledger=null,$currency=null){$this->ledger=$ledger?:new CreditLedgerService();$this->currency=$currency?:new CreditCurrencyAdapter();}
    public function packages(){$db=$this->ledger->database();$codes=array();foreach($this->currency->active()as$item)if(isset($item->code))$codes[strtoupper($item->code)]=$item;$rows=$db->all("SELECT x.*,p.code program_code,p.symbol FROM davvag_credit_package x JOIN davvag_credit_program p ON p.id=x.program_id WHERE x.status='ACTIVE' AND p.purchase_available='true' AND (x.active_from IS NULL OR x.active_from<=NOW()) AND (x.active_until IS NULL OR x.active_until>=NOW()) ORDER BY x.sort_order,x.id");$out=array();foreach($rows as$row){$code=strtoupper(isset($row->currency)?$row->currency:"");if(!isset($codes[$code]))continue;$row->currency_config=$codes[$code];$out[]=$row;}return$out;}
    public function createOrder($profileId,$packageId,$idempotencyKey){$idempotencyKey=CreditRules::idempotency($idempotencyKey);$db=$this->ledger->database();$preflight=$db->one("SELECT x.*,p.code program_code FROM davvag_credit_package x JOIN davvag_credit_program p ON p.id=x.program_id WHERE x.id=? LIMIT 1","i",array(intval($packageId)));if(!$preflight)throw new CreditException("Credit package is unavailable.");$this->currency->requireActive($preflight->currency);$wallet=$this->ledger->wallet($profileId,$preflight->program_code);return$db->transaction(function($txdb)use($profileId,$packageId,$idempotencyKey,$wallet){$existing=$txdb->one("SELECT * FROM davvag_credit_purchase_order WHERE profile_id=? AND idempotency_key=? LIMIT 1 FOR UPDATE","is",array(intval($profileId),$idempotencyKey));if($existing){if(intval($existing->package_id)!==intval($packageId))throw new CreditException("The idempotency key was already used with different parameters.");return$existing;}$package=$txdb->one("SELECT x.*,p.code program_code,p.purchase_available FROM davvag_credit_package x JOIN davvag_credit_program p ON p.id=x.program_id WHERE x.id=? LIMIT 1 FOR UPDATE","i",array(intval($packageId)));if(!$package||$package->status!=="ACTIVE"||!CreditRules::truthy($package->purchase_available))throw new CreditException("Credit package is unavailable.");$now=time();if((!empty($package->active_from)&&strtotime($package->active_from)>$now)||(!empty($package->active_until)&&strtotime($package->active_until)<$now))throw new CreditException("Credit package is unavailable.");$count=$txdb->one("SELECT COUNT(*) amount FROM davvag_credit_purchase_order WHERE profile_id=? AND package_id=? AND order_status IN('PAID','CREDITED')","ii",array(intval($profileId),intval($packageId)));if(CreditRules::truthy($package->first_purchase_only)&&intval($count->amount)>0)throw new CreditException("This package is available for a first purchase only.");if(intval($package->purchase_limit_per_profile)>0&&intval($count->amount)>=intval($package->purchase_limit_per_profile))throw new CreditException("The purchase limit for this package has been reached.");$id=$txdb->insert("davvag_credit_purchase_order",array("order_reference"=>"credit_order_".bin2hex(random_bytes(10)),"profile_id"=>intval($profileId),"wallet_id"=>intval($wallet->id),"package_id"=>intval($package->id),"package_code_snapshot"=>$package->package_code,"credit_amount_snapshot"=>intval($package->credit_amount),"bonus_amount_snapshot"=>intval($package->bonus_credit_amount),"price_minor_snapshot"=>intval($package->price_minor),"currency_snapshot"=>$package->currency,"payment_provider"=>$package->payment_channel,"provider_payment_reference"=>"","provider_status"=>"PENDING","order_status"=>"PAYMENT_PENDING","idempotency_key"=>$idempotencyKey,"created_at"=>date("Y-m-d H:i:s"),"expires_at"=>date("Y-m-d H:i:s",time()+3600),"paid_at"=>null,"credited_at"=>null,"credit_transaction_id"=>0,"refund_status"=>"NONE"));return$txdb->one("SELECT * FROM davvag_credit_purchase_order WHERE id=?","i",array($id));});}
    public function completeVerified($provider,$eventId,$orderReference,$providerReference,$payloadHash){$db=$this->ledger->database();$existing=$db->one("SELECT * FROM davvag_credit_payment_event WHERE provider=? AND provider_event_id=? LIMIT 1","ss",array($provider,$eventId));if($existing)return$this->orderById($existing->order_id);$order=$db->one("SELECT o.*,p.program_id,pr.code program_code FROM davvag_credit_purchase_order o JOIN davvag_credit_package p ON p.id=o.package_id JOIN davvag_credit_program pr ON pr.id=p.program_id WHERE o.order_reference=? LIMIT 1","s",array($orderReference));if(!$order)throw new CreditException("Purchase order was not found.");if($order->order_status==="CREDITED")return$order;$total=CreditRules::amount(intval($order->credit_amount_snapshot)+intval($order->bonus_amount_snapshot));$context=array("programCode"=>$order->program_code,"sourceApp"=>"davvag-credit-points","referenceType"=>"purchase-order","referenceId"=>$order->order_reference,"idempotencyKey"=>"purchase:".$order->id.":credit","description"=>"Purchased credit package ".$order->package_code_snapshot,"metadata"=>array("orderId"=>intval($order->id),"providerReference"=>$providerReference,"baseCredits"=>intval($order->credit_amount_snapshot),"bonusCredits"=>intval($order->bonus_amount_snapshot)));$this->ledger->credit($order->profile_id,$total,$context,"PURCHASE",null,true,function($txdb,$tx)use($provider,$eventId,$order,$providerReference,$payloadHash){$duplicate=$txdb->one("SELECT id FROM davvag_credit_payment_event WHERE provider=? AND provider_event_id=? LIMIT 1 FOR UPDATE","ss",array($provider,$eventId));if($duplicate)throw new CreditException("This payment event has already been processed.");$locked=$txdb->one("SELECT * FROM davvag_credit_purchase_order WHERE id=? LIMIT 1 FOR UPDATE","i",array(intval($order->id)));if(!$locked||$locked->order_status==="CREDITED")throw new CreditException("This purchase order has already been credited.");$eventDbId=$txdb->insert("davvag_credit_payment_event",array("provider"=>$provider,"provider_event_id"=>$eventId,"event_type"=>"PAYMENT_COMPLETED","payload_hash"=>$payloadHash,"signature_verified"=>"true","order_id"=>intval($order->id),"processing_status"=>"PROCESSED","processed_at"=>date("Y-m-d H:i:s"),"error_message"=>""));$txdb->updateById("davvag_credit_purchase_order",$order->id,array("provider_payment_reference"=>$providerReference,"provider_status"=>"COMPLETED","order_status"=>"CREDITED","paid_at"=>date("Y-m-d H:i:s"),"credited_at"=>date("Y-m-d H:i:s"),"credit_transaction_id"=>intval($tx->id)));});return$this->orderById($order->id);}
    public function orderById($id){return$this->ledger->database()->one("SELECT * FROM davvag_credit_purchase_order WHERE id=? LIMIT 1","i",array(intval($id)));}
    public function orderForProfile($id,$profileId){return$this->ledger->database()->one("SELECT * FROM davvag_credit_purchase_order WHERE id=? AND profile_id=? LIMIT 1","ii",array(intval($id),intval($profileId)));}
}
?>
